import './checkmark-draw.css';

export interface CheckmarkDrawProps {
  /** True draws the ring, then the tick. False clears both. */
  done: boolean;
  /** Text shown and announced once done, for example "Payment received". */
  label: string;
  size?: number;
  className?: string;
}

/** A ring and a check mark drawn stroke by stroke, with matching text. */
export function CheckmarkDraw({
  done,
  label,
  size = 88,
  className = '',
}: CheckmarkDrawProps) {
  return (
    <div className={`mg-checkmark ${className}`} data-done={done}>
      <svg width={size} height={size} viewBox='0 0 52 52' aria-hidden='true'>
        <circle
          className='mg-checkmark__ring'
          cx='26'
          cy='26'
          r='23'
          pathLength={1}
        />
        <path
          className='mg-checkmark__tick'
          d='M15 27 L23 34 L38 18'
          pathLength={1}
        />
      </svg>
      <p className='mg-checkmark__label' role='status'>
        {done ? label : ''}
      </p>
    </div>
  );
}

.mg-checkmark {
  display: grid;
  gap: 10px;
  justify-items: center;
  color: var(--mg-ink, #0c1738);
}

.mg-checkmark svg {
  fill: none;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.mg-checkmark__ring {
  stroke: #e1e8fb;
  stroke-width: 3;
  stroke-dasharray: 1;
  stroke-dashoffset: 0;
  transform: rotate(-90deg);
  transform-origin: center;
}

.mg-checkmark__tick {
  stroke: #3d6b00;
  stroke-width: 4;
  stroke-dasharray: 1;
  stroke-dashoffset: 1;
}

.mg-checkmark[data-done='true'] .mg-checkmark__ring {
  stroke: #3d6b00;
  animation: mg-checkmark-ring 520ms cubic-bezier(0.6, 0, 0.3, 1) both;
}

.mg-checkmark[data-done='true'] .mg-checkmark__tick {
  stroke-dashoffset: 0;
  animation: mg-checkmark-tick 320ms ease-out 480ms both;
}

.mg-checkmark__label {
  min-height: 1.4em;
  margin: 0;
  color: #3d6b00;
  font-weight: 700;
}

@keyframes mg-checkmark-ring {
  from {
    stroke-dashoffset: 1;
  }
}

@keyframes mg-checkmark-tick {
  from {
    stroke-dashoffset: 1;
  }
}

@media (prefers-reduced-motion: reduce) {
  .mg-checkmark[data-done='true'] .mg-checkmark__ring,
  .mg-checkmark[data-done='true'] .mg-checkmark__tick {
    animation: none;
  }
}
